                iteration_index,
                tsc_freq,
                &mut extra_submit_trace,
            );

            prefill_completion_trace.push(measure_prefill_completion_trace(
                prefill_submit,
                &slots.completions[..k_prefill],
                &mut seen[..k_prefill],
                tsc_freq,
                iteration_index,
            ));

            trace_outcomes.push(measure_trace_outcome(
                wq,
                &mut sentinel_comp,
                &operation_class,
                &slots.completions[..submitted],
                &mut seen[..submitted],
                k_prefill,
                iteration_index,
